from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
FACTS_DIR = ROOT / "data" / "facts"
OUT_DIR = Path(__file__).resolve().parent / "rag-questions"


def load_book(doc: str) -> tuple[dict, dict[str, dict], dict[str, list[int]]]:
    data = json.loads((FACTS_DIR / f"{doc}.json").read_text(encoding="utf-8"))
    facts_map = {f["id"]: f for f in data["facts"]}
    where: dict[str, list[int]] = {}
    for n, page in enumerate(data["pages"], start=1):
        for b in page["blocks"]:
            ids = b.get("ids", []) if b["t"] == "facts" else b.get("facts", [])
            for fid in ids:
                if n not in where.setdefault(fid, []):
                    where[fid].append(n)
    return data, facts_map, where


def make_records(doc: str, prefix: str, specs: list[tuple]) -> list[dict]:
    _, facts_map, where = load_book(doc)
    records = []
    for idx, spec in enumerate(specs, start=1):
        fids, qtype, diff, question, custom_ans = spec
        qid = f"{prefix}-Q{idx:03d}"
        if fids:
            pages = sorted({p for fid in fids for p in where[fid]})
            if custom_ans:
                ans = custom_ans
            else:
                ans = " · ".join(facts_map[fid]["statement"] for fid in fids)
        else:
            pages = []
            ans = custom_ans
        records.append({
            "qid": qid,
            "book": doc,
            "question": question,
            "answer": ans,
            "fact_ids": fids,
            "pages": pages,
            "type": qtype,
            "difficulty": diff,
        })
    return records


